const $=(s,root=document)=>root.querySelector(s);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=escapeHtml;
const url=s=>{try{const u=new URL(String(s));return ['https:','http:'].includes(u.protocol)?escapeHtml(u.href):'';}catch{return '';}};
const svg={
 home:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M8 13l3 3 5-6"/>',
 heart:'<path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78L12 21.23l8.84-8.84a5.5 5.5 0 0 0 0-7.78Z"/>',
 tasks:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 10 2 2 3-4M14 10h4M7 17h11"/>',
 image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 16-5-5L5 21"/>',
 wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 9h18m-5 5h2M6 5V3h13"/>',
 guests:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3.13a4 4 0 0 1 0 7.75M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>',
 vendors:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m-13 7h18"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
 team:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6M21 21v-2a5 5 0 0 0-4-5"/>',
 settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m19.4 15 .1.1 1.4 1.1-2 3.5-1.7-.7a8 8 0 0 1-2 1.2l-.2 1.8h-4l-.2-1.8a8 8 0 0 1-2-1.2l-1.7.7-2-3.5 1.4-1.1a8 8 0 0 1 0-2.3l-1.4-1.1 2-3.5 1.7.7a8 8 0 0 1 2-1.2L11 5h4l.2 1.8a8 8 0 0 1 2 1.2l1.7-.7 2 3.5-1.4 1.1a8 8 0 0 1 0 2.3Z" transform="translate(-1 -1) scale(.97)"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 5 5L20 7"/>',
 close:'<path d="M18 6 6 18M6 6l12 12"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>', down:'<path d="m6 9 6 6 6-6"/>',
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 sparkles:'<path d="m12 3 1.8 5.2L19 10l-5.2 1.8L12 17l-1.8-5.2L5 10l5.2-1.8L12 3ZM5 18l.7 1.3L7 20l-1.3.7L5 22l-.7-1.3L3 20l1.3-.7L5 18ZM19 17l.7 1.3L21 19l-1.3.7L19 21l-.7-1.3L17 19l1.3-.7L19 17Z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 flag:'<path d="M4 22V4m0 0c4-3 7 3 11 0 2-1 3-1 5 0v12c-4-3-7 3-11 0-2-1-3-1-5 0"/>',
 trend:'<path d="m3 17 7-7 4 4 7-7M15 7h6v6"/>',
 search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',
 edit:'<path d="M13 6 18 11M3 21l4.7-1 12-12a2 2 0 0 0-4-4l-12 12L3 21Z"/>',
 trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 10v7m4-7v7"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',
 logout:'<path d="M10 17l5-5-5-5m5 5H3m9-9h6a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-6"/>',
 link:'<path d="M13 5h6v6M19 5l-9 9M19 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
 pin:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 filter:'<path d="M4 7h16M7 12h10m-7 5h4"/>',
 dot:'<circle cx="12" cy="12" r="5"/>',
 refresh:'<path d="M20 11a8 8 0 0 0-14.4-4.8L3 9m0-6v6h6M4 13a8 8 0 0 0 14.4 4.8L21 15m0 6v-6h-6"/>',
 more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
 gift:'<rect x="3" y="9" width="18" height="12" rx="2"/><path d="M12 9v12M3 13h18M12 9c-6-2-7-7-4-7 2 0 4 4 4 7Zm0 0c6-2 7-7 4-7-2 0-4 4-4 7Z"/>'
};
const icon=(name,size=19,extra='')=>`<svg class="icon ${extra}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svg[name]||svg.heart}</svg>`;
const nav=[['dashboard','Overview','home'],['tasks','To-do list','tasks'],['inspiration','Inspiration','image'],['budget','Budget tracker','wallet'],['guests','Guest list','guests'],['vendors','Vendors','vendors'],['events','Wedding timeline','calendar'],['planners','Planning team','team'],['settings','Settings','settings']];
const navHeading={dashboard:'Overview',tasks:'To-do list',inspiration:'Inspiration board',budget:'Budget tracker',guests:'Guest list',vendors:'Wedding vendors',events:'Wedding timeline',planners:'Your planning team',settings:'Wedding settings'};
const state={data:null,mode:'local',view:'dashboard',actor:localStorage.getItem('wedding-actor')||'',taskFilter:'all',taskCategory:'all',search:'',mobileNav:false,folder:'',saving:false};
const app=$('#app');
const currency=(n)=>new Intl.NumberFormat('en-TT',{style:'currency',currency:state.data?.settings?.currency||'TTD',maximumFractionDigits:0}).format(Number(n)||0);
const dateFmt=(d,options={month:'short',day:'numeric',year:'numeric'})=>d?new Date(`${d}T12:00:00`).toLocaleDateString('en-GB',options):'Not set';
const total=(k)=>state.data?.[k]?.length||0;
const completed=()=>state.data.tasks.filter(x=>x.status==='done').length;
const percent=(n,d)=>d?Math.round(n/d*100):0;
function dateUntil(d){if(!d)return null;return Math.max(0,Math.ceil((new Date(`${d}T12:00:00`).getTime()-Date.now())/86400000));}
function couple(){const s=state.data.settings;return s.partnerOne&&s.partnerTwo?`${s.partnerOne} & ${s.partnerTwo}`:s.partnerOne||s.partnerTwo||'Your wedding';}
function avatar(name='?'){const initial=String(name||'?').trim().charAt(0).toUpperCase();return `<span class="avatar" title="${text(name)}">${text(initial)}</span>`;}
function pill(value){return `<span class="pill pill-${text(value||'other').replace(/[^a-zA-Z]/g,'-').toLowerCase()}">${text(String(value||'Other').replaceAll('_',' '))}</span>`;}
const emptyArt=(ico,title,desc,button,entity)=>`<div class="empty"><div class="empty-icon">${icon(ico,28)}</div><h3>${title}</h3><p>${desc}</p>${button?`<button class="btn btn-primary" data-action="add" data-entity="${entity}">${icon('plus',16)} ${button}</button>`:''}</div>`;

function sidebar(){return `<aside class="sidebar ${state.mobileNav?'sidebar-open':''}">
<div class="side-top"><button class="brand" data-action="navigate" data-view="dashboard" aria-label="Go to overview"><span class="brand-symbol">f<span>♡</span></span><span class="brand-copy">forever <i>&</i> always.<small>THE WEDDING EDITION</small></span></button><button class="mobile-close" data-action="mobile-toggle" aria-label="Close menu">${icon('close')}</button></div>
<div class="nav-block"><span class="nav-label">YOUR WEDDING</span><nav aria-label="Main navigation">${nav.slice(0,7).map(([view,label,ic])=>`<button class="nav-item ${state.view===view?'selected':''}" data-action="navigate" data-view="${view}">${icon(ic,19)}<span>${label}</span>${view==='tasks'?`<small class="nav-count">${total('tasks')}</small>`:''}</button>`).join('')}</nav></div>
<div class="nav-block nav-second"><span class="nav-label">WORKSPACE</span><nav>${nav.slice(7).map(([view,label,ic])=>`<button class="nav-item ${state.view===view?'selected':''}" data-action="navigate" data-view="${view}">${icon(ic,19)}<span>${label}</span></button>`).join('')}</nav></div>
<div class="sidebar-bottom"><div class="side-card"><div class="side-card-flower">✧</div><strong>Something wonderful<br>is on the way.</strong><p>One task at a time, one beautiful memory at a time.</p><button data-action="navigate" data-view="tasks">Keep planning ${icon('arrow',15)}</button></div><div class="side-footer">MADE FOR LOVE STORIES · 2027 ♡</div></div></aside>`;}
function pageHeader(){const subtitle={dashboard:'Here is your wedding planning at a glance.',tasks:'Big dreams are made of the little details.',inspiration:'Collect the things that make your hearts skip a beat.',budget:'Make room for what matters most.',guests:'All your favourite people, in one place.',vendors:'Your dream team for a beautiful day.',events:'Every milestone leading to I do.',planners:'The people making it all happen.',settings:'Make this lovely little space truly yours.'};
const canAdd=['tasks','inspiration','budget','guests','vendors','events','planners'].includes(state.view);
return `<header class="topbar"><button class="hamburger" data-action="mobile-toggle" aria-label="Open navigation">${icon('menu',22)}</button><div class="breadcrumb">OUR WEDDING <span>/</span> <strong>${text(navHeading[state.view])}</strong></div><div class="topbar-right"><div class="sync-pill" title="${state.mode==='drive'?'Saved to the shared Google Drive folder':'Stored on this computer for testing'}"><span class="sync-dot"></span>${state.mode==='drive'?'Drive connected':'Local test mode'}</div><button class="round-icon refresh" data-action="refresh" title="Refresh data" aria-label="Refresh data">${icon('refresh',17)}</button><button class="profile" data-action="navigate" data-view="planners" title="Planning team">${avatar(state.actor||'Planner')}<span>${text(state.actor||'Planner')}</span></button></div></header>
<div class="page-heading"><div><div class="page-kicker">${state.view==='dashboard'?'A LITTLE BIT OF MAGIC':'FOREVER STARTS HERE'}</div><h1>${state.view==='dashboard'?`Hello, ${text(state.actor||'lovely people')} <span class="heading-heart">♡</span>`:text(navHeading[state.view])}</h1><p>${subtitle[state.view]}</p></div>${canAdd?`<button class="btn btn-primary heading-add" data-action="add" data-entity="${state.view}">${icon('plus',18)} Add ${state.view==='inspiration'?'inspiration':state.view==='planners'?'planner':state.view==='guests'?'guest':state.view==='events'?'event':state.view==='tasks'?'task':state.view==='budget'?'expense':'vendor'}</button>`:`${state.view==='dashboard'?`<button class="btn btn-primary heading-add" data-action="add" data-entity="tasks">${icon('plus',18)} New task</button>`:''}`}</div>`;}
function mobileBottom(){return `<nav class="mobile-bottom" aria-label="Mobile navigation">${[['dashboard','home','Home'],['tasks','tasks','Tasks'],['inspiration','image','Ideas'],['budget','wallet','Budget'],['more','menu','More']].map(([view,ic,name])=>`<button class="mobile-bottom-item ${state.view===view?'selected':''}" data-action="${view==='more'?'mobile-toggle':'navigate'}" ${view!=='more'?`data-view="${view}"`:''}>${icon(ic,21)}<span>${name}</span></button>`).join('')}</nav>`;}
function shell(){app.innerHTML=`<div class="workspace">${sidebar()}<div class="mobile-mask ${state.mobileNav?'visible':''}" data-action="mobile-toggle"></div><div class="work-main">${pageHeader()}<main class="page-content" id="page-content">${renderView()}</main><footer class="app-footer"><span>Thoughtfully made for your happily ever after.</span><span>♡ forever & always.</span></footer></div>${mobileBottom()}</div>`;}
function render(){if(state.data)shell();}
function renderView(){switch(state.view){case 'dashboard':return dashboard();case 'tasks':return tasks();case 'inspiration':return inspiration();case 'budget':return budget();case 'guests':return guests();case 'vendors':return vendors();case 'events':return events();case 'planners':return planners();case 'settings':return settings();default:return dashboard();}}

function dashboard(){const d=state.data,s=d.settings,days=dateUntil(s.weddingDate),budgetTotal=d.budget.reduce((a,v)=>a+Number(v.estimated||0),0),spent=d.budget.reduce((a,v)=>a+Number(v.actual||0),0);
const priority=d.tasks.filter(t=>t.status!=='done').sort((a,b)=>(a.priority==='high'?-1:1)-(b.priority==='high'?-1:1)).slice(0,4);
const upcoming=[...d.events].filter(e=>!e.done&&(!e.date||e.date>=new Date().toISOString().slice(0,10))).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')).slice(0,3);
return `<div class="dashboard-view"><section class="hero"><div class="hero-glow"></div><div class="hero-content"><div class="hero-overline">${icon('sparkles',16)} YOUR LOVE STORY, YOUR WAY</div><h2>${text(couple())}<em>Forever begins here.</em></h2><p>${text(s.tagline||'A beautiful beginning, together.')}</p><div class="hero-meta"><span>${icon('calendar',16)} ${s.weddingDate?dateFmt(s.weddingDate):'Date to be announced'}</span><span>${icon('pin',16)} ${text(s.location||s.venue||'A place filled with love')}</span></div></div><div class="hero-countdown"><span class="count-label">COUNTING DOWN TO I DO</span><b>${days===null?'♡':days}</b><small>${days===null?'SET YOUR DATE':days===0?'IT’S THE BIG DAY!':days===1?'DAY TO GO':'DAYS TO GO'}</small><button data-action="navigate" data-view="settings">${days===null?'Add wedding date':'Edit details'} ${icon('arrow',13)}</button></div></section>
<div class="stats-grid"><div class="stat-card"><span class="stat-icon rose">${icon('tasks',22)}</span><div class="stat-body"><span>TASKS COMPLETED</span><strong>${completed()} <small>/ ${total('tasks')}</small></strong><div class="mini-progress"><span style="width:${percent(completed(),total('tasks'))}%"></span></div><p>${percent(completed(),total('tasks'))}% of your checklist done</p></div></div>
<div class="stat-card"><span class="stat-icon sage">${icon('guests',22)}</span><div class="stat-body"><span>GUESTS ATTENDING</span><strong>${d.guests.filter(g=>g.rsvp==='attending').length} <small>/ ${total('guests')}</small></strong><p>Confirmed lovely people</p></div></div>
<div class="stat-card"><span class="stat-icon cream">${icon('wallet',22)}</span><div class="stat-body"><span>ESTIMATED BUDGET</span><strong class="stat-money">${currency(budgetTotal)}</strong><p>${currency(spent)} spent so far</p></div></div>
<div class="stat-card"><span class="stat-icon lavender">${icon('heart',22)}</span><div class="stat-body"><span>INSPIRATION SAVED</span><strong>${total('inspiration')}</strong><p>Lovely ideas collected</p></div></div></div>
<div class="dash-columns"><section class="panel"><div class="section-heading"><div><div class="section-eyebrow">KEEP THE MOMENTUM</div><h3>Up next on your list</h3></div><button class="text-link" data-action="navigate" data-view="tasks">View all ${icon('arrow',16)}</button></div>${priority.length?`<div class="priority-list">${priority.map(t=>`<div class="priority-row"><button class="round-check" data-action="set-status" data-id="${text(t.id)}" data-status="done" title="Mark done">${icon('check',13)}</button><div class="priority-text"><b>${text(t.title)}</b><span>${text(t.category||'Planning')}${t.assignee?' · '+text(t.assignee):''}</span></div>${pill(t.priority||'medium')}</div>`).join('')}</div>`:emptyArt('tasks','All caught up!','Add a to-do to start planning the next lovely thing.','Add a task','tasks')}</section>
<section class="panel"><div class="section-heading"><div><div class="section-eyebrow">A LITTLE LOOK AHEAD</div><h3>Upcoming moments</h3></div><button class="text-link" data-action="navigate" data-view="events">Timeline ${icon('arrow',16)}</button></div>${upcoming.length?`<div class="event-shortlist">${upcoming.map(e=>`<div class="mini-event"><div class="event-date-chip"><strong>${e.date?new Date(`${e.date}T12:00:00`).getDate():'♡'}</strong><span>${e.date?dateFmt(e.date,{month:'short'}):'TBD'}</span></div><div><b>${text(e.title)}</b><small>${text(e.location||e.time||'Details to follow')}</small></div></div>`).join('')}</div>`:emptyArt('calendar','So much to look forward to','Add a date for a fitting, tasting, or special milestone.','Add an event','events')}</section></div>
<div class="dash-columns dash-bottom"><section class="panel"><div class="section-heading"><div><div class="section-eyebrow">DREAM A LITTLE</div><h3>Your inspiration corner</h3></div><button class="text-link" data-action="navigate" data-view="inspiration">See moodboard ${icon('arrow',16)}</button></div>${d.inspiration.length?`<div class="preview-grid">${d.inspiration.slice(0,3).map(x=>`<button data-action="edit" data-entity="inspiration" data-id="${text(x.id)}" class="preview-image">${x.imageUrl||x.imageId?`<img src="${x.imageId?'/api/images/'+encodeURIComponent(x.imageId):url(x.imageUrl)}" alt="${text(x.title)}" loading="lazy">`:`<div>${icon('heart',30)}</div>`}</button>`).join('')}</div>`:emptyArt('image','Your dream board awaits','Save photos, colour palettes and inspiration.','Add an idea','inspiration')}</section>
<section class="panel"><div class="section-heading"><div><div class="section-eyebrow">MADE POSSIBLE BY</div><h3>Our planning people</h3></div><button class="text-link" data-action="navigate" data-view="planners">See team ${icon('arrow',16)}</button></div><div class="team-preview">${d.planners.length?`<div class="avatar-stack">${d.planners.slice(0,6).map(x=>avatar(x.name)).join('')}</div><h4>${total('planners')} wonderful planner${total('planners')===1?'':'s'}</h4><p>Making every special detail happen together.</p>`:`<div class="team-empty-icon">${icon('team',25)}</div><h4>Better together</h4><p>Invite your planning team by sharing your site link and password.</p><button class="btn btn-secondary" data-action="add" data-entity="planners">${icon('plus',16)} Add a planner</button>`}</div></section></div>
${state.mode==='local'?`<div class="mode-banner">${icon('flag',18)} <div><b>You're in local test mode.</b> Your changes are saved on this computer, not shared online. Connect Google Drive before deploying on Vercel.</div><button data-action="navigate" data-view="settings">Setup details ${icon('arrow',14)}</button></div>`:''}
</div>`;}
function tasks(){const all=state.data.tasks,categories=['all',...new Set(all.map(t=>t.category||'Planning'))];
const filtered=all.filter(t=>(state.taskCategory==='all'||t.category===state.taskCategory)&& (state.taskFilter==='all'||state.taskFilter===t.status) && (!state.search||[t.title,t.notes,t.category,t.assignee].some(v=>String(v||'').toLowerCase().includes(state.search.toLowerCase()))));
const cols=[['todo','To do','Start with one little step.'],['in_progress','In progress','The magic is happening.'],['done','Completed','Another thing to celebrate!']];
return `<div class="toolbar"><div class="search-field">${icon('search',18)}<input type="search" id="task-search" placeholder="Search your tasks..." aria-label="Search tasks" value="${text(state.search)}"></div><div class="toolbar-controls"><select class="select-quiet" id="task-category" aria-label="Filter task category">${categories.map(x=>`<option value="${text(x)}" ${state.taskCategory===x?'selected':''}>${x==='all'?'All categories':text(x)}</option>`).join('')}</select><div class="segmented" aria-label="Filter by status">${[['all','All'],['todo','To do'],['in_progress','In progress'],['done','Done']].map(([k,l])=>`<button class="${state.taskFilter===k?'active':''}" data-action="task-filter" data-filter="${k}">${l}</button>`).join('')}</div></div></div>
<div class="tasks-progress"><div><span>Our planning progress</span><b>${completed()} of ${total('tasks')} completed</b></div><div class="long-progress"><span style="width:${percent(completed(),total('tasks'))}%"></span></div><strong>${percent(completed(),total('tasks'))}%</strong></div>
${!all.length?`<div class="panel">${emptyArt('tasks','It all starts with a list','Add a task yourself, or begin with a ready-made 20-item wedding checklist.','Add your first task','tasks')}<div class="starter-wrap"><button class="btn btn-ghost" data-action="starter">${icon('sparkles',16)} Load starter wedding checklist</button></div></div>`:
`<div class="kanban">${cols.filter(c=>state.taskFilter==='all'||state.taskFilter===c[0]).map(([status,name,desc])=>{const items=filtered.filter(t=>t.status===status);return `<section class="kanban-col"><div class="column-head"><div><span class="status-indicator si-${status}"></span><h3>${name}</h3><small>${items.length}</small></div><p>${desc}</p></div><div class="column-cards">${items.map(t=>taskCard(t)).join('')||`<div class="kanban-empty">No tasks here yet ♡</div>`}</div>${status==='todo'?`<button class="add-inline" data-action="add" data-entity="tasks">${icon('plus',17)} Add another task</button>`:''}</section>`;}).join('')}</div>`}
${all.length>0?`<div class="below-hint">${icon('sparkles',17)} A little progress every day adds up to something wonderful.</div>`:''}</div>`;}
function taskCard(t){return `<article class="task-card" data-action="edit" data-entity="tasks" data-id="${text(t.id)}" role="button" tabindex="0" aria-label="Edit ${text(t.title)}"><div class="task-card-top">${pill(t.category||'Planning')}<button class="card-more" data-action="edit" data-entity="tasks" data-id="${text(t.id)}" aria-label="Edit task">${icon('more',18)}</button></div><h4>${text(t.title)}</h4>${t.notes?`<p class="task-desc">${text(t.notes)}</p>`:''}<div class="task-card-bottom"><span class="priority-label ${t.priority==='high'?'priority-high':''}"><span></span>${text(t.priority||'medium')} priority</span>${t.dueDate?`<span class="due">${icon('calendar',14)} ${dateFmt(t.dueDate,{month:'short',day:'numeric'})}</span>`:''}</div><div class="task-card-foot">${t.assignee?`<span class="task-assignee">${avatar(t.assignee)} ${text(t.assignee)}</span>`:`<span class="task-unassigned">Unassigned</span>`}<div class="task-actions">${t.status!=='todo'?`<button data-action="set-status" data-id="${text(t.id)}" data-status="todo" aria-label="Move to to do" title="Move to to do">${icon('refresh',15)}</button>`:''}${t.status!=='in_progress'&&t.status!=='done'?`<button data-action="set-status" data-id="${text(t.id)}" data-status="in_progress" aria-label="Start task" title="Start task">${icon('arrow',15)}</button>`:''}${t.status!=='done'?`<button class="mark-done" data-action="set-status" data-id="${text(t.id)}" data-status="done" aria-label="Mark complete" title="Mark complete">${icon('check',15)}</button>`:`<span class="completed-mark">${icon('check',15)} Done</span>`}</div></div></article>`;}
function inspiration(){const d=state.data.inspiration;return `<div class="mood-intro"><div><div class="section-eyebrow">THE THINGS WE LOVE</div><h3>Our shared moodboard <span>✳</span></h3><p>Save those beautiful details, and the big day will slowly come into focus.</p></div><button class="btn btn-secondary" data-action="add" data-entity="inspiration">${icon('upload',17)} Add photo or link</button></div>${d.length?`<div class="masonry">${d.map((x,i)=>`<article class="inspo-card"><button class="inspo-photo photo-${i%4}" data-action="edit" data-entity="inspiration" data-id="${text(x.id)}" aria-label="Edit ${text(x.title)}">${x.imageId||x.imageUrl?`<img src="${x.imageId?'/api/images/'+encodeURIComponent(x.imageId):url(x.imageUrl)}" alt="${text(x.title)}" loading="lazy" onerror="this.style.display='none'">`:`<span class="inspo-fallback">${icon('heart',42)}<small>LOVE THIS IDEA</small></span>`}<span class="photo-hover">${icon('edit',18)} Edit idea</span></button><div class="inspo-caption"><span>${text(x.category||'Inspiration')}</span><h4>${text(x.title)}</h4>${x.notes?`<p>${text(x.notes)}</p>`:''}</div></article>`).join('')}</div>`:`<div class="panel">${emptyArt('image','A little space for big dreams','Upload dresses, bouquets, décor and invitations. Your uploaded photos will live in the shared wedding folder.','Add inspiration','inspiration')}</div>`}</div>`;}
function budget(){const d=state.data.budget,planned=d.reduce((a,x)=>a+Number(x.estimated||0),0),spent=d.reduce((a,x)=>a+Number(x.actual||0),0),remaining=planned-spent,ratio=percent(spent,planned);
return `<div class="budget-summary"><div class="budget-main"><div class="light-eyebrow">OUR WEDDING BUDGET</div><strong>${currency(planned)}</strong><p>The total we are planning to spend</p><div class="budget-progress"><span style="width:${Math.min(ratio,100)}%"></span></div><div class="budget-range"><span>${currency(spent)} spent</span><span>${ratio}% used</span></div></div><div class="budget-side"><div class="budget-tile"><span class="stat-icon rose">${icon('wallet',22)}</span><div><small>ACTUAL SPENDING</small><strong>${currency(spent)}</strong><p>Across ${d.length} budget items</p></div></div><div class="budget-tile"><span class="stat-icon sage">${icon('trend',22)}</span><div><small>${remaining>=0?'ESTIMATED REMAINING':'OVER ESTIMATE'}</small><strong>${currency(Math.abs(remaining))}</strong><p>${remaining>=0?'Still available in the budget':'Consider updating your estimates'}</p></div></div></div></div>
<section class="panel data-panel"><div class="section-heading"><div><div class="section-eyebrow">EVERY PENNY HAS A PURPOSE</div><h3>Budget breakdown</h3></div><button class="btn btn-secondary" data-action="add" data-entity="budget">${icon('plus',17)} Add item</button></div>
${d.length?`<div class="responsive-table"><table><thead><tr><th>ITEM</th><th>CATEGORY</th><th class="money-cell">ESTIMATED</th><th class="money-cell">ACTUAL</th><th>PAID</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td><b>${text(x.title)}</b></td><td>${pill(x.category||'Other')}</td><td class="money-cell">${currency(x.estimated)}</td><td class="money-cell">${currency(x.actual)}</td><td><button class="toggle-paid ${x.paid?'is-paid':''}" data-action="toggle-paid" data-id="${text(x.id)}" title="Toggle payment status">${icon(x.paid?'check':'clock',14)} ${x.paid?'Paid':'Unpaid'}</button></td><td><button class="row-edit" data-action="edit" data-entity="budget" data-id="${text(x.id)}" aria-label="Edit budget item">${icon('edit',17)}</button></td></tr>`).join('')}</tbody></table></div>`:emptyArt('wallet','A meaningful budget for a meaningful day','Start adding estimated costs as you find venues, caterers, outfits and all the little things.','Add a budget item','budget')}</section></div>`;}
function guests(){const d=state.data.guests;const attending=d.filter(x=>x.rsvp==='attending').length,pending=d.filter(x=>!x.rsvp||x.rsvp==='pending').length,declined=d.filter(x=>x.rsvp==='declined').length;
return `<div class="guest-summary">${[['Guests invited',d.length,'guests'],['Attending',attending,'check'],['Awaiting RSVP',pending,'clock'],['Not attending',declined,'heart']].map(([label,n,ic])=>`<div class="guest-stat"><div class="guest-stat-icon">${icon(ic,21)}</div><div><small>${label}</small><strong>${n}</strong></div></div>`).join('')}</div><section class="panel data-panel"><div class="section-heading"><div><div class="section-eyebrow">SURROUNDED BY LOVE</div><h3>Our guest list</h3></div><button class="btn btn-secondary" data-action="add" data-entity="guests">${icon('plus',17)} Add guest</button></div>${d.length?`<div class="responsive-table"><table><thead><tr><th>GUEST</th><th>GROUP</th><th>RSVP STATUS</th><th>MEAL</th><th>+1</th><th></th></tr></thead><tbody>${d.map(g=>`<tr><td><div class="guest-name">${avatar(g.name)} <b>${text(g.name)}</b></div></td><td>${text(g.group||'—')}</td><td><select class="table-select rsvp-${text(g.rsvp||'pending')}" data-rsvp="${text(g.id)}" aria-label="RSVP for ${text(g.name)}"><option value="pending" ${!g.rsvp||g.rsvp==='pending'?'selected':''}>Awaiting reply</option><option value="attending" ${g.rsvp==='attending'?'selected':''}>Attending</option><option value="declined" ${g.rsvp==='declined'?'selected':''}>Not attending</option></select></td><td>${text(g.meal||'—')}</td><td>${g.plusOne?'Yes':'—'}</td><td><button class="row-edit" data-action="edit" data-entity="guests" data-id="${text(g.id)}" aria-label="Edit guest">${icon('edit',17)}</button></td></tr>`).join('')}</tbody></table></div>`:emptyArt('guests','The people who mean the world','Add your favourite people and track RSVPs, meal preferences, and plus-ones.','Add a guest','guests')}</section></div>`;}
function vendors(){const d=state.data.vendors;return `<div class="section-note">${icon('heart',18)} Great celebrations take a great team. Keep every vendor contact, quote, and booking in one lovely place.</div>${d.length?`<div class="vendor-grid">${d.map(v=>`<article class="vendor-card"><div class="vendor-header"><div class="vendor-graphic">${icon('vendors',24)}</div>${pill(v.status||'researching')}</div><span class="vendor-category">${text(v.category||'Wedding vendor')}</span><h3>${text(v.name)}</h3><div class="vendor-lines">${v.phone?`<div>${icon('clock',15)} ${text(v.phone)}</div>`:''}${v.email?`<div>${icon('mail',15)} ${text(v.email)}</div>`:''}${v.website?`<a href="${url(v.website)}" target="_blank" rel="noopener noreferrer">${icon('link',15)} Visit website</a>`:''}${!v.phone&&!v.email&&!v.website?`<span>Add contact details when ready.</span>`:''}</div><div class="vendor-footer"><strong>${v.amount?currency(v.amount):'No quote yet'}</strong><button class="btn btn-outline" data-action="edit" data-entity="vendors" data-id="${text(v.id)}">View details ${icon('arrow',15)}</button></div></article>`).join('')}</div>`:`<section class="panel">${emptyArt('vendors','Meet your wedding dream team','Add your venues, florists, caterers, photographers and other wonderful vendors.','Add a vendor','vendors')}</section>`}</div>`;}
function events(){const d=[...state.data.events].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));
return `<div class="timeline-intro"><div>${icon('calendar',29)}<h3>Every step closer to forever</h3><p>Keep fittings, tastings, payments, and all your special milestones on the calendar.</p></div><button class="btn btn-secondary" data-action="add" data-entity="events">${icon('plus',17)} Add milestone</button></div>${d.length?`<div class="timeline-list">${d.map((x,i)=>`<div class="timeline-item ${x.done?'timeline-done':''}"><div class="timeline-line"><span>${icon(x.done?'check':'calendar',18)}</span></div><div class="timeline-content"><div class="timeline-meta">${x.date?dateFmt(x.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'}):'Date to be confirmed'}${x.time?' · '+text(x.time):''}</div><div class="timeline-head"><h3>${text(x.title)}</h3>${x.done?pill('done'):''}</div>${x.location?`<p>${icon('pin',15)} ${text(x.location)}</p>`:''}${x.notes?`<div class="timeline-notes">${text(x.notes)}</div>`:''}<div class="timeline-actions"><button class="text-link" data-action="edit" data-entity="events" data-id="${text(x.id)}">${icon('edit',15)} Edit</button><button class="text-link" data-action="toggle-event" data-id="${text(x.id)}">${icon(x.done?'refresh':'check',15)} ${x.done?'Mark upcoming':'Mark completed'}</button></div></div></div>`).join('')}</div>`:`<section class="panel">${emptyArt('calendar','Your wedding story in milestones','Add your wedding date, fitting appointments, venue visits, tastings and other important dates.','Add a milestone','events')}</section>`}</div>`;}
function planners(){const d=state.data.planners;return `<div class="team-hero"><div class="team-hero-icon">${icon('team',36)}</div><div><div class="section-eyebrow">IT TAKES A VILLAGE</div><h2>Better together.</h2><p>Give each member of your team a place to collaborate on every detail. Everyone uses the shared website password.</p></div><button class="btn btn-primary" data-action="add" data-entity="planners">${icon('plus',17)} Add planner</button></div><div class="team-identity panel"><div><h3>Who are you planning as?</h3><p>Choose your name so changes can be labelled on the activity feed. This is not a separate account or login.</p></div><select id="actor-select" class="field-input identity-select" aria-label="Choose your display name"><option value="">Select your name</option>${d.map(p=>`<option value="${text(p.name)}" ${state.actor===p.name?'selected':''}>${text(p.name)}</option>`).join('')}</select></div><div class="section-heading team-subhead"><div><div class="section-eyebrow">THE PEOPLE BEHIND THE MAGIC</div><h3>Wedding planning team <span class="count-round">${d.length}</span></h3></div></div>${d.length?`<div class="planner-grid">${d.map(x=>`<article class="planner-card"><div class="planner-avatar">${avatar(x.name)}</div><h3>${text(x.name)}</h3><p>${text(x.role||'Wedding planner')}</p>${x.email?`<small>${text(x.email)}</small>`:''}<button class="btn btn-outline" data-action="edit" data-entity="planners" data-id="${text(x.id)}">${icon('edit',16)} Edit planner</button></article>`).join('')}</div>`:`<section class="panel">${emptyArt('team','The best team starts here','Add your name, your partner, or the friends and family helping you plan.','Add a planner','planners')}</section>`}<div class="access-note">${icon('flag',19)} <div><b>One shared password for your whole team.</b><p>Adding someone here shows their name and helps assign tasks. To access the site, you'll still need to share the website URL and password privately. All planners have the same editing permissions.</p></div></div></div>`;}
function settings(){const s=state.data.settings;return `<div class="settings-grid"><section class="panel settings-panel"><div class="section-heading"><div><div class="section-eyebrow">YOUR DAY, YOUR DETAILS</div><h3>Wedding details</h3></div>${icon('heart',22)}</div><form id="settings-form"><div class="form-grid"><div class="field"><label for="partnerOne">First partner's name</label><input class="field-input" id="partnerOne" name="partnerOne" value="${text(s.partnerOne)}" placeholder="Your name"></div><div class="field"><label for="partnerTwo">Second partner's name</label><input class="field-input" id="partnerTwo" name="partnerTwo" value="${text(s.partnerTwo)}" placeholder="Your partner's name"></div><div class="field"><label for="weddingDate">Wedding date</label><input class="field-input" id="weddingDate" name="weddingDate" type="date" value="${text(s.weddingDate)}"></div><div class="field"><label for="currency">Budget currency</label><select class="field-input" id="currency" name="currency">${['TTD','USD','GBP','EUR','CAD','JMD','BBD'].map(x=>`<option value="${x}" ${s.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="venue">Wedding venue</label><input class="field-input" id="venue" name="venue" value="${text(s.venue)}" placeholder="Venue name"></div><div class="field"><label for="location">Wedding location</label><input class="field-input" id="location" name="location" value="${text(s.location)}" placeholder="e.g. Trinidad & Tobago"></div><div class="field full"><label for="tagline">A little love note</label><input class="field-input" id="tagline" name="tagline" maxlength="120" value="${text(s.tagline)}" placeholder="A beautiful beginning, together."></div></div><button class="btn btn-primary" type="submit">${icon('check',17)} Save wedding details</button></form></section>
<div class="settings-aside"><section class="panel"><div class="section-heading"><div><div class="section-eyebrow">SAVED WITH CARE</div><h3>Your wedding data</h3></div>${icon('settings',21)}</div><div class="storage-type"><span class="storage-icon ${state.mode==='drive'?'connected':''}">${icon(state.mode==='drive'?'check':'flag',22)}</span><div><b>${state.mode==='drive'?'Google Drive connected':'Local testing mode'}</b><p>${state.mode==='drive'?'Updates and photos are stored in the shared Drive folder.':'Changes are saved to this computer and will not persist on Vercel until Drive is configured.'}</p></div></div><a class="btn btn-outline wide-button" href="${url(state.folder)}" target="_blank" rel="noopener noreferrer">${icon('link',17)} Open wedding Drive folder</a><button class="btn btn-outline wide-button" data-action="export">${icon('download',17)} Export wedding data (JSON)</button></section>
<section class="panel"><div class="section-heading"><div><div class="section-eyebrow">WHAT'S BEEN HAPPENING</div><h3>Recent activity</h3></div></div>${state.data.activity.length?`<div class="activity-feed">${state.data.activity.slice(0,8).map(a=>`<div class="activity-item"><span>${icon('heart',15)}</span><div><p><b>${text(a.actor)}</b> ${text(a.text)}</p><small>${new Date(a.at).toLocaleString()}</small></div></div>`).join('')}</div>`:`<p class="muted">Your team's updates will appear here as you start planning.</p>`}</section>
<button class="btn btn-logout" data-action="logout">${icon('logout',17)} Sign out of wedding planner</button></div></div>`;}
const sections={
 tasks:{singular:'task',fields:[['title','Task name','text','e.g. Book the photographer'],['category','Category','select',['Planning','Venue','Guests','Photography','Catering','Decor','Attire','Stationery','Entertainment','Ceremony','Beauty','Transport','Budget','Other']],['status','Status','select',[['todo','To do'],['in_progress','In progress'],['done','Completed']]],['priority','Priority','select',[['low','Low'],['medium','Medium'],['high','High']]],['assignee','Assigned to','assignee'],['dueDate','Due date','date'],['notes','Notes','textarea','Anything the team should know…']]},
 inspiration:{singular:'inspiration',fields:[['title','A name for this idea','text','e.g. White roses and eucalyptus'],['category','Category','select',['Flowers','Reception','Ceremony','Attire','Colours','Stationery','Details','Other']],['upload','Upload an image (up to 3 MB)','file'],['imageUrl','Or paste an image URL','url','https://...'],['notes','Notes','textarea','What do you love about this idea?']]},
 budget:{singular:'budget item',fields:[['title','Budget item','text','e.g. Bridal bouquet'],['category','Category','select',['Venue','Catering','Photography','Attire','Decor','Stationery','Entertainment','Ceremony','Transport','Beauty','Other']],['estimated','Estimated amount','number','0'],['actual','Amount spent so far','number','0'],['paid','Fully paid','checkbox'],['notes','Notes','textarea','Details or payment reminders…']]},
 guests:{singular:'guest',fields:[['name','Guest name','text','First and last name'],['group','Group','select',['Family','Friends','Wedding party','Colleagues','Other']],['rsvp','RSVP status','select',[['pending','Awaiting reply'],['attending','Attending'],['declined','Not attending']]],['meal','Meal / dietary preference','text','e.g. Vegetarian'],['plusOne','Bringing a plus-one','checkbox'],['notes','Notes','textarea','Anything else to remember…']]},
 vendors:{singular:'vendor',fields:[['name','Business / vendor name','text','e.g. Bloom Florals'],['category','Service type','select',['Venue','Catering','Photography','Videography','Decor','Florist','Attire','Entertainment','Beauty','Transport','Cake','Other']],['status','Booking status','select',[['researching','Researching'],['contacted','Contacted'],['booked','Booked']]],['phone','Phone','text','Contact number'],['email','Email','email','hello@example.com'],['website','Website','url','https://...'],['amount','Quote / cost','number','0'],['notes','Notes','textarea','Quotes, availability and questions…']]},
 events:{singular:'milestone',fields:[['title','Event or milestone','text','e.g. Venue tasting'],['date','Date','date'],['time','Time','time'],['location','Location','text','Where will it be?'],['done','Completed','checkbox'],['notes','Notes','textarea','Reminders or extra details…']]},
 planners:{singular:'planner',fields:[['name','Planner name','text','Name of your planner'],['role','Role','select',['Bride / Groom','Partner','Maid of honor','Best man','Wedding coordinator','Family','Friend','Wedding planner','Other']],['email','Email (optional)','email','For reference only — no invitations are emailed']]}
};
function fieldHtml([key,label,type,extra],original){let val=original?.[key];
if(val===undefined||val===null){if(key==='status')val='todo';else if(key==='priority')val='medium';else if(key==='rsvp')val='pending';else if(key==='category')val=Array.isArray(extra)?(Array.isArray(extra[0])?extra[0][0]:extra[0]):'';else val='';}
const id=`modal-${key}`;
if(type==='textarea')return `<div class="field full"><label for="${id}">${label}</label><textarea class="field-input" rows="3" name="${key}" id="${id}" placeholder="${text(extra)}">${text(val)}</textarea></div>`;
if(type==='checkbox')return `<div class="field full check-field"><label for="${id}"><input type="checkbox" name="${key}" id="${id}" ${val?'checked':''}><span>${label}</span></label></div>`;
if(type==='file')return `<div class="field full"><label for="${id}">${label}</label><div class="file-drop">${icon('upload',21)}<input type="file" id="${id}" name="${key}" accept="image/png,image/jpeg,image/webp,image/gif" aria-label="Choose image"><small>JPG, PNG, WEBP or GIF · 3 MB max · saved privately</small></div>${original?.imageId?'<small class="field-helper">The previously uploaded image will stay unless you choose a new one.</small>':''}</div>`;
if(type==='assignee'){const values=['',...new Set(state.data.planners.map(p=>p.name).concat(val?[val]:[]))];return `<div class="field"><label for="${id}">${label}</label><select class="field-input" name="${key}" id="${id}">${values.map(v=>`<option value="${text(v)}" ${val===v?'selected':''}>${v?text(v):'Unassigned'}</option>`).join('')}</select></div>`;}
if(type==='select'){const opts=extra.map(x=>Array.isArray(x)?x:[x,x]);if(val&&!opts.some(x=>x[0]===val))opts.push([val,val]);return `<div class="field"><label for="${id}">${label}</label><select class="field-input" name="${key}" id="${id}">${opts.map(([value,name])=>`<option value="${text(value)}" ${value===val?'selected':''}>${text(name)}</option>`).join('')}</select></div>`;}
return `<div class="field ${type==='url'?'full':''}"><label for="${id}">${label}</label><input class="field-input" id="${id}" name="${key}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${text(val)}" placeholder="${text(type==='text'||type==='url'||type==='email'||type==='number'?extra:'')}" ${(['title','name'].includes(key))?'required':''}></div>`;}
function openModal(entity,id){const def=sections[entity];if(!def)return;const item=id?state.data[entity].find(x=>x.id===id):null;
if(id&&!item){toast('This item could not be found. Refresh and try again.','error');return;}
const modal=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="section-eyebrow">${item?'MAKE A LITTLE CHANGE':'A LOVELY NEW DETAIL'}</div><h2 id="modal-title">${item?'Edit':'Add'} ${def.singular}</h2></div><button class="round-icon" data-action="close-modal" aria-label="Close dialog">${icon('close',20)}</button></div><form id="modal-form" data-entity="${entity}" data-id="${id||''}"><div class="modal-scroll"><div class="form-grid">${def.fields.map(f=>fieldHtml(f,item)).join('')}</div>${entity==='inspiration'&&item&&(item.imageId||item.imageUrl)?`<div class="current-image"><span>Current image</span><img src="${item.imageId?'/api/images/'+encodeURIComponent(item.imageId):url(item.imageUrl)}" alt="Current inspiration" loading="lazy"></div>`:''}</div><div class="modal-actions">${item?`<button type="button" class="btn btn-danger" data-action="delete" data-entity="${entity}" data-id="${text(id)}">${icon('trash',16)} Delete</button>`:''}<div class="modal-action-right"><button type="button" class="btn btn-outline" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary" id="modal-save">${icon('check',16)} ${item?'Save changes':'Add '+def.singular}</button></div></div></form></div></div>`;
$('#modal-root').innerHTML=modal;document.body.classList.add('modal-open');$('#modal-title')?.setAttribute('tabindex','-1');setTimeout(()=>$('#modal-form input:not([type="file"]),#modal-form select')?.focus(),30);
}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');}
let toastTimeout;
function toast(message,type='success'){const root=$('#toast-root');root.innerHTML=`<div class="toast ${type==='error'?'toast-error':''}">${icon(type==='error'?'flag':'check',18)}<span>${text(message)}</span><button data-action="close-toast" aria-label="Dismiss">${icon('close',16)}</button></div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>root.innerHTML='',5100);}
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options});let j;try{j=await response.json();}catch{throw Error('The server returned an unexpected response.');}
if(response.status===401&&path!=='/api/login'){window.location.href='/login';throw Error('Your session expired. Please sign in again.');}
if(!response.ok)throw Error(j.error||'Something went wrong.');return j;}
async function change(entity,op,value={},id,actor=state.actor){if(state.saving)return;state.saving=true;try{const result=await api('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entity,op,value,id,actor:actor||'A planner'})});state.data=result.data;closeModal();render();toast(op==='delete'?'Removed successfully.':op==='create'?'Added to your wedding planner.':'Changes saved for the whole team.');}catch(e){toast(e.message,'error');}finally{state.saving=false;}}
async function saveModal(form){if(state.saving)return;const entity=form.dataset.entity,id=form.dataset.id,original=id?state.data[entity].find(x=>x.id===id):null;const data=new FormData(form),value={};
for(const [key,label,type] of sections[entity].fields){if(type==='file')continue;value[key]=type==='checkbox'?Boolean(form.elements[key]?.checked):type==='number'?Math.max(0,Number(data.get(key))||0):String(data.get(key)||'');}
const button=$('#modal-save');button.disabled=true;button.innerHTML=`${icon('refresh',16)} Saving…`;
try{
 if(entity==='inspiration'){
  value.imageId=original?.imageId||'';
  const imageFile=form.elements.upload?.files?.[0];
  if(imageFile){if(imageFile.size>3000000)throw Error('Images must be smaller than 3 MB.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(imageFile.type))throw Error('Please choose a JPG, PNG, WEBP or GIF image.');
    const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read image.'));reader.readAsDataURL(imageFile);});
    const uploaded=await api('/api/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({base64,mime:imageFile.type,name:imageFile.name})});value.imageId=uploaded.imageId;value.imageUrl='';
  }else if(value.imageUrl&&value.imageUrl!==original?.imageUrl){value.imageId='';}
  if(!value.imageId&&!value.imageUrl)throw Error('Please choose a photo or paste an image URL.');
 }
 await change(entity,id?'update':'create',value,id);
}catch(e){toast(e.message,'error');}finally{if($('#modal-save')){button.disabled=false;button.innerHTML=`${icon('check',16)} Save`;}}
}
function navigate(view){state.view=view;state.mobileNav=false;state.search='';state.taskCategory='all';state.taskFilter='all';render();window.scrollTo({top:0,behavior:'instant'});}
async function refresh(){try{const result=await api('/api/data');state.data=result.data;state.mode=result.mode;state.folder=result.driveFolderUrl;render();toast('Your planning workspace is up to date.');}catch(e){toast(e.message,'error');}}
function downloadExport(){const blob=new Blob([JSON.stringify(state.data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`wedding-planner-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}

document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b){if(e.target.id==='modal-backdrop')closeModal();return;}
 const action=b.dataset.action;const entity=b.dataset.entity,id=b.dataset.id;
 if(action==='navigate')return navigate(b.dataset.view);
 if(action==='mobile-toggle'){state.mobileNav=!state.mobileNav;return render();}
 if(action==='add')return openModal(entity);
 if(action==='edit')return openModal(entity,id);
 if(action==='close-modal')return closeModal();
 if(action==='close-toast')return $('#toast-root').innerHTML='';
 if(action==='refresh')return refresh();
 if(action==='task-filter'){state.taskFilter=b.dataset.filter;return render();}
 if(action==='starter'){if(!confirm('Add the 20-item starter wedding checklist?'))return;return change('starter','create',{});}
 if(action==='export')return downloadExport();
 if(action==='delete'){if(!confirm('Remove this item from the shared wedding planner? This cannot be undone.'))return;return change(entity,'delete',{},id);}
 if(action==='set-status')return change('tasks','update',{status:b.dataset.status},id);
 if(action==='toggle-paid'){const item=state.data.budget.find(x=>x.id===id);if(item)return change('budget','update',{paid:!item.paid},id);}
 if(action==='toggle-event'){const item=state.data.events.find(x=>x.id===id);if(item)return change('events','update',{done:!item.done},id);}
 if(action==='logout'){try{await api('/api/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});}finally{window.location.replace('/login');}return;}
});
document.addEventListener('submit',async e=>{
 if(e.target.id==='modal-form'){e.preventDefault();await saveModal(e.target);}
 if(e.target.id==='settings-form'){e.preventDefault();const d=new FormData(e.target);const value=Object.fromEntries(d.entries());await change('settings','update',value);}
});
document.addEventListener('change',async e=>{
 if(e.target.id==='actor-select'){state.actor=e.target.value;localStorage.setItem('wedding-actor',state.actor);render();toast(state.actor?`Planning as ${state.actor}.`:'Choose your name to label future updates.');}
 if(e.target.id==='task-category'){state.taskCategory=e.target.value;render();}
 if(e.target.matches('[data-rsvp]'))await change('guests','update',{rsvp:e.target.value},e.target.dataset.rsvp);
});
document.addEventListener('input',e=>{
 if(e.target.id==='task-search'){
  const position=e.target.selectionStart||0;state.search=e.target.value;const content=$('#page-content');if(!content)return;content.innerHTML=tasks();const input=$('#task-search');input?.focus();input?.setSelectionRange(position,position);
 }
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.matches('article[role="button"]')){e.preventDefault();e.target.click();}});
(async function load(){
 try{const result=await api('/api/data');state.data=result.data;state.mode=result.mode;state.folder=result.driveFolderUrl;if(!state.data.planners.some(p=>p.name===state.actor)){state.actor='';localStorage.removeItem('wedding-actor');}render();}
 catch(e){app.innerHTML=`<div class="load-error"><div>${icon('heart',36)}</div><h2>Your wedding space isn't ready yet</h2><p>${text(e.message)}</p><button class="btn btn-primary" onclick="location.reload()">${icon('refresh',17)} Try again</button><a href="/login">Back to login</a></div>`;}
})();

// Refresh shared Drive data while the workspace is idle, so planners see teammates' edits.
setInterval(async()=>{
 if(!state.data||state.saving||document.hidden||$('#modal-backdrop')||
    ['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
 try{const result=await api('/api/data');if(result.data.updatedAt!==state.data.updatedAt){
   state.data=result.data;state.mode=result.mode;state.folder=result.driveFolderUrl;render();
 }}catch{/* Manual refresh remains available if the connection is temporarily unavailable. */}
},60000);
